	for i, q := range qs {
		var qq = []byte(q[:int(DefaultBufferSize)] + strings.Repeat(" ", i*100) + q[int(DefaultBufferSize):])
		var obj interface{}
		require.NotNil(t, NewStreamDecoder(bytes.NewReader(qq)).Decode(&obj))
	}
}

