type ErrReader struct {
	src  string
	read int
	err  error
}

func (er *ErrReader) Read(p []byte) (int, error) {
	if er.read >= len(er.src) {
		return 0, er.err
	}
	n := copy(p, []byte(er.src[er.read:]))
	er.read += n
	return n, nil
}

